import React, { useEffect, useState } from 'react'
import './App.css'

function App() {

  const [backendData, setBackendData] = useState([{}]);

  useEffect(() => {
     fetch("http://localhost:3001/api").then(
       response => response.json()
     ).then(
        data => {
          setBackendData(data)  
        }
     )
  }, [] )

  return (
    <div>
      {/* als de data nog niet gevonden is */}
      {(typeof backendData.bedrijven === 'undefined') ? (
        <p>Found nothing</p>
      ) : (
        backendData.bedrijven.map((item, i) => 
          <p style={{display: "inline-block"}} id={i}>{item}:ㅤ</p> 
        )
      )} 
      <br/>
      {(typeof backendData.bedrijfsnaam === 'undefined') ? (
        <p>Found nothing</p>
      ) : (
        backendData.bedrijfsnaam.map((item, i) => 
          <p style={{display: "inline-block"}} id={i}> ({i}) {item}  ㅤ</p> 
        )
      )}
      <br/>
      {(typeof backendData.adres === 'undefined') ? (
        <p>Found nothing</p>
      ) : (
        backendData.adres.map((item, i) => 
          <p style={{display: "inline-block"}} id={i}> ({i}) {item}  ㅤ</p> 
        )
      )}
      <br/>
      {(typeof backendData.woonplaats === 'undefined') ? (
        <p>Found nothing</p>
      ) : (
        backendData.woonplaats.map((item, i) => 
          <p style={{display: "inline-block"}} id={i}> ({i}) {item}  ㅤ</p> 
        )
      )}
      <br/>
      {(typeof backendData.Telnr === 'undefined') ? (
        <p>Found nothing</p>
      ) : (
        backendData.Telnr.map((item, i) => 
          <p style={{display: "inline-block"}} id={i}> ({i}) {item}  ㅤ</p> 
        )
      )}

{/* backendData.bedrijfsnaam.map((item, i) => 
          <p style={{display: "inline-block"}} id={i}>{item}:ㅤ</p> 
        ),
        backendData.adres.map((item, i) => 
          <p style={{display: "inline-block"}} id={i}>{item}:ㅤ</p> 
        ),
        backendData.woonplaats.map((item, i) => 
          <p style={{display: "inline-block"}} id={i}>{item}:ㅤ</p> 
        ),
        backendData.Telnr.map((item, i) => 
          <p style={{display: "inline-block"}} id={i}>{item}:ㅤ</p> 
        ) */}

      {/* <h1>titel</h1>

      <div className="form">
        <label>bedrijfsnaam:ㅤ</label><input type="text" name="bedrijfsnaam"></input>
        <label>adres:ㅤ</label><input type="text" name="adres"></input>
        <label>woonplaats:ㅤ</label><input type="text" name="woonplaats"></input>
        <label>Telnr:ㅤ</label><input type="text" name="Telnr"></input>

        <button>Submit</button>
      </div> */}
    </div>
  );

}

export default App;
